import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../data/auth_controller.dart';

class RegisterScreen extends StatefulWidget { const RegisterScreen({super.key}); @override State<RegisterScreen> createState() => _RegisterScreenState(); }
class _RegisterScreenState extends State<RegisterScreen> {
 final _form = GlobalKey<FormState>(); final _name = TextEditingController(); final _email = TextEditingController(); final _password = TextEditingController(); bool _loading = false;
 @override void dispose(){_name.dispose();_email.dispose();_password.dispose();super.dispose();}
 Future<void> _submit() async { if(!_form.currentState!.validate()) return; setState(()=>_loading=true); try { await context.read<AuthController>().register(_name.text.trim(),_email.text.trim(),_password.text); if(!mounted)return; ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Cadastro realizado. Entre com suas credenciais.'))); Navigator.pop(context); } catch(e){ if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString()))); } finally {if(mounted)setState(()=>_loading=false);} }
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Cadastro')),body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Form(key:_form,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Crie sua conta',style:Theme.of(context).textTheme.headlineSmall,textAlign:TextAlign.center),const SizedBox(height:24),TextFormField(controller:_name,decoration:const InputDecoration(labelText:'Nome',border:OutlineInputBorder()),validator:(v)=>v==null||v.trim().length<5?'Informe seu nome (mínimo 5 caracteres)':null),const SizedBox(height:16),TextFormField(controller:_email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'E-mail',border:OutlineInputBorder()),validator:(v)=>v==null||!v.contains('@')?'Informe um e-mail válido':null),const SizedBox(height:16),TextFormField(controller:_password,obscureText:true,decoration:const InputDecoration(labelText:'Senha',border:OutlineInputBorder()),validator:(v)=>v==null||v.length<8?'A senha deve ter ao menos 8 caracteres':null),const SizedBox(height:24),ElevatedButton(onPressed:_loading?null:_submit,child:_loading?const CircularProgressIndicator():const Text('Cadastrar'))]))))));
}
